content.solutionCode:
.dashboard-shell {
  width: 100%;
  max-width: 900px;
  border: 1px solid #e2e8f0;
  padding: 24px;
  display: flex;
  gap: 24px;
}

.dashboard-sidebar {
  padding: 16px;
  background: #f1f5f9;
  border-radius: 6px;
  width: 240px;
  flex-shrink: 0;
}

.dashboard-main {
  padding: 16px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  flex-grow: 1;
}
